activity.result = (function() {
    // === Utility Functions ===
    function logCertWF(logLevel, message) {
        var logMsg = "[RITM: " + ritmNumber + "] " + message;
        var gr = new GlideRecord('x_1784056_sixscape_log');
        gr.initialize();
        gr.script = "Get Certificate Workflow";
        gr.log_level = logLevel;
        gr.message = logMsg;
        gr.application = "Sixscape IDC";
        gr.insert();

        // Mirror to workflow and system logs
        if (logLevel == "Info") {
            workflow.info(logMsg);
        } else {
            workflow.error(logMsg);
        }
    }

    function setCommonHeaders(request, token) {
        request.setRequestHeader("Authorization", token);
        request.setRequestHeader("Content-Type", "application/json");
        request.setRequestHeader("User-Agent", "snow");
    }

    function setMID(request) {
        if (midServer) {
            request.setMIDServer(midServer);
            request.setEccParameter("skip_sensor", "true");
        }
    }

    function executeREST(request, tag, returnLocationIfFlag) {
        request.setHttpTimeout(30000);
        var response = request.execute();
        var body = response.getBody();
        var status = response.getStatusCode();
        logCertWF("Info", tag + ": HTTP " + status);
        if (response.haveError()) {
            // Try extracting the title, else default to generic message
            var errorMsg = "REST call failed [" + status + "]";
            if (body) {
                try {
                    var parsed = JSON.parse(body);
                    errorMsg += ": " + (parsed.title || "");
                } catch (e) {
                    errorMsg += ": " + body;
                }
            }
            throw new Error(errorMsg + ". See logs for details.");
        }
        if (returnLocationIfFlag) return response.getHeader('Location');
        try {
            return JSON.parse(body);
        } catch (e) {
            throw new Error("Failed to parse " + tag + " response.");
        }
    }

    // === Main Logic ===
    try {
        var ritmNumber = workflow.scratchpad.req_item_number;
        var endpoint = gs.getProperty("x_1784056_sixscape.End Point") || "";
        if (endpoint.endsWith("/")) endpoint = endpoint.slice(0, -1);
        var midServer = gs.getProperty("x_1784056_sixscape.Mid Server Name") || "";
        var deviceVar = current.variables.device;
        var deviceName = deviceVar.device_name.toString();
		var deviceId = deviceVar.device_id.toString();

        var tokenObj, response, authToken, payload;
        var commonName = current.variables.common_name.toString();
        var createdDate = current.variables.certificate_creation_time.toString();

        logCertWF("Info", "[Sixscape] Starting revoke certificate workflow for: " + deviceName);
        // 1. Get Token
        tokenObj = new GetToken();
        response = tokenObj.TestConnection();
        if (!response || response.length < 2 || response[0] !== 200)
            throw "Token retrieval failed!";
        authToken = "Bearer " + JSON.parse(response[1]).authToken;
        payload = {
            reason: "UNSPECIFIED",
            comment: "Revocation from sevicenow by user - " + current.opened_by.first_name
        };
		logCertWF("Info", "Payload for revoke certificate: " + JSON.stringify(payload));
        var encodedCertId = encodeURIComponent(commonName + "|" + createdDate);
        var postReq = new sn_ws.RESTMessageV2();
        setMID(postReq);
        postReq.setHttpMethod("post");
        setCommonHeaders(postReq, authToken);
        postReq.setEndpoint(endpoint + "/v1/certificate/" + encodedCertId + "/revoke");
        postReq.setRequestBody(JSON.stringify(payload));
        var certLocation = executeREST(postReq, "Revoke Certificate");
        logCertWF("Info", "Revoke requested for the certificate : " + commonName);

        var gr = new GlideRecordSecure("x_1784056_sixscape_device");
        gr.addQuery("device_id", deviceId);
        gr.query();
        while (gr.next()) {
            gr.certificate_status = "REVOKED";
            gr.update();
            logCertWF("Info", "Updated device data for device_id: " + deviceId);
        }
        logCertWF("Info", "[Sixscape] Revoke certificate workflow completed.");
        return "true";

    } catch (err) {
        var message = "ERROR in Revoke Workflow : " + (error && error.message ? error.message : error);
        logCertWF("Error", message);
        current.comments = (current.comments || "") + "\n" + message;
        current.stage = "closed_incomplete";
        current.state = 4;
        var req = current.request && current.request.getRefRecord && current.request.getRefRecord();
        if (req) {
            req.state = 4;
            req.request_state = "closed_incomplete";
            req.update();
        }
        return "false";
    }
})();

